      await expect(updateEvent('evt', {}, oneOff({ status: 'CONFIRMED' }))).rejects.toThrow(
        'Forbidden',
      );
      expect(db.event('evt')).toMatchObject({ status: 'PROPOSED' });
      expect(audit()).toEqual([]);
    });

