import { beforeEach, describe, expect, it, vi } from 'vitest';

vi.mock('@/config', () => ({ getConfig: vi.fn() }));
vi.mock('@/lib/prisma', () => ({
  prisma: { event: { findMany: vi.fn() }, eventReminder: { create: vi.fn() } },
