}));
vi.mock('./slack-blocks', () => ({ buildEventSlack: vi.fn(() => ({ fallback: 'f' })) }));
vi.mock('./email', () => ({ buildEventEmail: vi.fn(() => ({ html: '<p>', text: 'p' })) }));
vi.mock('./messages', () => ({
  buildReminderMessage: vi.fn(() => ({ subject: 'Rappel', body: 'Demain' })),
}));
vi.mock('./notifications', () => ({
  deliver: vi.fn(async () => ({ sent: 1, failed: 0 })),
  getTranslate: vi.fn(async () => (key: string) => key),
  repeatSummaryFor: vi.fn(async () => null),
  toNotificationData: vi.fn(() => ({})),
}));

const { getConfig } = await import('@/config');
const { prisma } = await import('@/lib/prisma');
const { deliver, toNotificationData } = await import('./notifications');
const { buildReminderMessage } = await import('./messages');
const { buildEventEmail } = await import('./email');
const { buildEventSlack } = await import('./slack-blocks');
const { emailsOfHolders } = await import('@/lib/notifications/recipients');
const { reminderDueAt, runReminderTick } = await import('./reminders');

const PARIS = 'Europe/Paris';

function setConfig(options: { enabled?: boolean; channel?: string } = {}) {
  const enabled = options.enabled ?? true;
  vi.mocked(getConfig).mockReturnValue({
    bde: { timezone: PARIS, defaultLocale: 'fr' },
    modules: { enabled: enabled ? ['events'] : [] },
    events: { categories: [], reminderHour: 18 },
    notifications: { eventReminder: options.channel ?? 'email' },
  } as unknown as ReturnType<typeof getConfig>);
}

interface StoredOccurrence {
  occurrenceStart: Date;
  title: string | null;
  description: string | null;
  location: string | null;
  categoryKey: string | null;
  status: 'DRAFT' | 'CONFIRMED' | null;
  startsAt: Date | null;
  endsAt: Date | null;
  assigneesOverridden: boolean;
  confirmationNotifiedAt: Date | null;
  updatedAt: Date;
  assignees: { login: string; user: { fullName: string; email: string } | null }[];
}

interface StoredEvent {
  id: string;
  title: string;
  description: string | null;
  location: string | null;
  categoryKey: string;
  status: 'DRAFT' | 'CONFIRMED';
  updatedAt: Date;
  occurrences: StoredOccurrence[];
  startsAt: Date;
  endsAt: Date;
  repeat: unknown;
  recurrenceUntil: Date | null;
  confirmationNotifiedAt: Date | null;
  assignees: { login: string; user: { fullName: string; email: string } | null }[];
  cancellations: { occurrenceStart: Date }[];
}

function event(overrides: Partial<StoredEvent> = {}): StoredEvent {
  return {
    id: 'evt1',
    title: 'Soirée',
    description: null,
    location: null,
    categoryKey: 'soiree',
    status: 'CONFIRMED',
    updatedAt: new Date('2026-09-01T10:00:00Z'),
    occurrences: [],
    // Saturday 10 Oct 2026, 20:00 Paris (UTC+2)
    startsAt: new Date('2026-10-10T18:00:00Z'),
    endsAt: new Date('2026-10-10T21:00:00Z'),
    repeat: null,
    recurrenceUntil: null,
    confirmationNotifiedAt: new Date('2026-09-01T10:00:00Z'),
    assignees: [{ login: 'alice', user: { fullName: 'Alice', email: 'alice@x.fr' } }],
    cancellations: [],
    ...overrides,
  };
}

/** A tiny in-memory stand-in for the unique (event, occurrence) index. */
function fakeClaimTable() {
  const claimed = new Set<string>();
  vi.mocked(prisma.eventReminder.create).mockImplementation((async ({
    data,
  }: {
    data: { eventId: string; occurrenceStart: Date };
  }) => {
    const key = `${data.eventId}:${data.occurrenceStart.getTime()}`;
    if (claimed.has(key)) {
      throw Object.assign(new Error('Unique constraint failed'), { code: 'P2002' });
    }
    claimed.add(key);
    return data;
  }) as never);
  return claimed;
}

beforeEach(() => {
  vi.clearAllMocks();
  vi.spyOn(console, 'error').mockImplementation(() => undefined);
  setConfig();
  fakeClaimTable();
});

describe('reminderDueAt', () => {
  it('is reminderHour on the local day before the occurrence', () => {
    // 10 Oct 20:00 Paris → due 9 Oct 18:00 Paris = 16:00 UTC (summer time)
    expect(reminderDueAt(new Date('2026-10-10T18:00:00Z'), PARIS, 18)).toEqual(
      new Date('2026-10-09T16:00:00Z'),
    );
  });

  it('uses the local day, so an after-midnight start is reminded two UTC days earlier', () => {
    // 11 Oct 00:30 Paris = 10 Oct 22:30 UTC → local day is the 11th → due 10 Oct 18:00 Paris
    expect(reminderDueAt(new Date('2026-10-10T22:30:00Z'), PARIS, 18)).toEqual(
      new Date('2026-10-10T16:00:00Z'),
    );
  });

  it('handles the DST change between the reminder and the event', () => {
    // Sun 25 Oct 2026 09:00 Paris (UTC+1) → due Sat 24 Oct 18:00 Paris (UTC+2) = 16:00 UTC
    expect(reminderDueAt(new Date('2026-10-25T08:00:00Z'), PARIS, 18)).toEqual(
      new Date('2026-10-24T16:00:00Z'),
    );
  });
});

describe('runReminderTick', () => {
  it('does nothing when the events module is disabled', async () => {
    setConfig({ enabled: false });
    await expect(runReminderTick(new Date('2026-10-09T17:00:00Z'))).resolves.toEqual({
      claimed: 0,
    });
    expect(prisma.event.findMany).not.toHaveBeenCalled();
  });

  it('only queries events that have something confirmed: a confirmed event, or a draft with a date confirmed alone', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([]);
    await runReminderTick(new Date('2026-10-09T17:00:00Z'));
    const where = JSON.stringify(vi.mocked(prisma.event.findMany).mock.calls[0]?.[0]);
    expect(where).toContain('"status":"CONFIRMED"');
    expect(where).toContain('"occurrences":{"some":{"status":"CONFIRMED"}}');
  });

  it('keeps looking at a series until its end, and at an event that has not happened yet', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([]);
    await runReminderTick(new Date('2026-10-09T17:00:00Z'));
    const where = JSON.stringify(vi.mocked(prisma.event.findMany).mock.calls[0]?.[0]);
    // a series (it has an end) can have a date to come whatever its first date was; the others only if they are to come
    expect(where).toContain('{"recurrenceUntil":{"not":null}}');
    expect(where).toContain('"startsAt":{"gt":');
  });

  it('does not remind a draft event', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event({ status: 'DRAFT' })] as never);
    const result = await runReminderTick(new Date('2026-10-09T16:00:00Z'));
    expect(result.claimed).toBe(0);
    expect(deliver).not.toHaveBeenCalled();
  });

  it('does not send before the reminder is due', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    // 15:59 UTC on 9 Oct = 17:59 Paris, one minute early
    await runReminderTick(new Date('2026-10-09T15:59:00Z'));
    expect(prisma.eventReminder.create).not.toHaveBeenCalled();
    expect(deliver).not.toHaveBeenCalled();
  });

  it('sends once the reminder is due, to the members in charge', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    const result = await runReminderTick(new Date('2026-10-09T16:00:00Z'));
    expect(result.claimed).toBe(1);
    expect(deliver).toHaveBeenCalledTimes(1);
    expect(deliver).toHaveBeenCalledWith('eventReminder', expect.anything(), ['alice@x.fr']);
  });

  it('says tomorrow for a reminder on time, today for one that goes out late (after a restart)', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    await runReminderTick(new Date('2026-10-09T16:00:00Z'));
    expect(vi.mocked(buildReminderMessage).mock.calls[0]?.[4]).toBe('tomorrow');

    vi.clearAllMocks();
    fakeClaimTable();
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    // The server was down all of the day before: back at 10:00 Paris on the day itself.
    await runReminderTick(new Date('2026-10-10T08:00:00Z'));
    expect(vi.mocked(buildReminderMessage).mock.calls[0]?.[4]).toBe('today');
  });

  it('sends the designed e-mail, with the same day as the plain text, and no calendar file', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    await runReminderTick(new Date('2026-10-09T16:00:00Z'));

    const call = vi.mocked(buildEventEmail).mock.calls[0];
    expect(call?.[0]).toBe('tomorrow');
    expect(call?.[6]).toBeUndefined(); // no .ics for a reminder
    expect(deliver).toHaveBeenCalledWith(
      'eventReminder',
      expect.objectContaining({ email: { html: '<p>', text: 'p' } }),
      ['alice@x.fr'],
    );

    vi.clearAllMocks();
    fakeClaimTable();
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    await runReminderTick(new Date('2026-10-10T08:00:00Z')); // the day itself, after a downtime
    expect(vi.mocked(buildEventEmail).mock.calls[0]?.[0]).toBe('today');
  });

  it('sends the Slack message with the same day as the plain text', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    await runReminderTick(new Date('2026-10-09T16:00:00Z'));

    expect(vi.mocked(buildEventSlack).mock.calls[0]?.[0]).toBe('tomorrow');
    expect(deliver).toHaveBeenCalledWith(
      'eventReminder',
      expect.objectContaining({ slack: { fallback: 'f' } }),
      ['alice@x.fr'],
    );

    vi.clearAllMocks();
    fakeClaimTable();
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    await runReminderTick(new Date('2026-10-10T08:00:00Z')); // the day itself, after a downtime
    expect(vi.mocked(buildEventSlack).mock.calls[0]?.[0]).toBe('today');
  });

  it('builds the e-mail of the reminder channel, not of another notification', async () => {
    const { withEmailContent } = await import('@/lib/notifications/email-card');
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    await runReminderTick(new Date('2026-10-09T16:00:00Z'));

    expect(vi.mocked(withEmailContent).mock.calls[0]?.[0]).toBe('eventReminder');
  });

  it('never sends the same reminder twice, however many ticks run', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    for (const minutes of [0, 5, 10, 15, 600]) {
      await runReminderTick(new Date(Date.parse('2026-10-09T16:00:00Z') + minutes * 60_000));
    }
    expect(deliver).toHaveBeenCalledTimes(1);
  });

  it('never sends twice across a restart (a fresh process reads the same claim table)', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    await runReminderTick(new Date('2026-10-09T16:05:00Z'));
    // "Restart": nothing in memory survives except the database rows.
    vi.resetModules();
    await runReminderTick(new Date('2026-10-09T16:10:00Z'));
    expect(deliver).toHaveBeenCalledTimes(1);
  });

  it('lets only one of two concurrent instances send', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    const now = new Date('2026-10-09T17:00:00Z');
    await Promise.all([runReminderTick(now), runReminderTick(now)]);
    expect(deliver).toHaveBeenCalledTimes(1);
  });

  it('catches up if the instance was down at the usual time', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    // Back online at 11:00 Paris on the day of the event (due since the evening
    // before, start at 20:00): the reminder still goes out.
    await runReminderTick(new Date('2026-10-10T09:00:00Z'));
    expect(deliver).toHaveBeenCalledTimes(1);
  });

  it('does not send for an occurrence that has already started', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    await runReminderTick(new Date('2026-10-10T18:30:00Z'));
    expect(deliver).not.toHaveBeenCalled();
  });

  it('does not remind a cancelled occurrence but still reminds the next one', async () => {
    const series = event({
      repeat: { freq: 'WEEKLY', interval: 1 },
      recurrenceUntil: new Date('2026-10-31T00:00:00Z'),
      cancellations: [{ occurrenceStart: new Date('2026-10-10T18:00:00Z') }],
    });
    vi.mocked(prisma.event.findMany).mockResolvedValue([series] as never);

    await runReminderTick(new Date('2026-10-09T17:00:00Z'));
    expect(deliver).not.toHaveBeenCalled();

    await runReminderTick(new Date('2026-10-16T17:00:00Z'));
    expect(deliver).toHaveBeenCalledTimes(1);
  });

  it('reminds each occurrence of a series separately', async () => {
    const series = event({
      repeat: { freq: 'WEEKLY', interval: 1 },
      recurrenceUntil: new Date('2026-10-31T00:00:00Z'),
    });
    vi.mocked(prisma.event.findMany).mockResolvedValue([series] as never);

    await runReminderTick(new Date('2026-10-09T17:00:00Z'));
    await runReminderTick(new Date('2026-10-16T17:00:00Z'));
    await runReminderTick(new Date('2026-10-16T18:00:00Z'));

    expect(deliver).toHaveBeenCalledTimes(2);
  });

  it('skips events confirmed after the reminder was due (members were just told)', async () => {
    const late = event({ confirmationNotifiedAt: new Date('2026-10-09T17:30:00Z') });
    vi.mocked(prisma.event.findMany).mockResolvedValue([late] as never);
    await runReminderTick(new Date('2026-10-09T18:00:00Z'));
    expect(deliver).not.toHaveBeenCalled();
  });

  it('does not send when the claim fails for a reason other than "already claimed"', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);
    vi.mocked(prisma.eventReminder.create).mockRejectedValue(new Error('db down'));
    await expect(runReminderTick(new Date('2026-10-09T17:00:00Z'))).resolves.toEqual({
      claimed: 0,
    });
    expect(deliver).not.toHaveBeenCalled();
  });

  describe('when nobody is in charge to write to', () => {
    const now = new Date('2026-10-09T17:00:00Z');

    it('goes to the people who can manage the events, not to no one', async () => {
      vi.mocked(emailsOfHolders).mockResolvedValue(['owner@x.fr', 'resp@x.fr']);
      vi.mocked(prisma.event.findMany).mockResolvedValue([event({ assignees: [] })] as never);

      await runReminderTick(now);

      expect(emailsOfHolders).toHaveBeenCalledExactlyOnceWith('events.validate');
      expect(deliver).toHaveBeenCalledWith('eventReminder', expect.anything(), [
        'owner@x.fr',
        'resp@x.fr',
      ]);
    });

    it('does the same when the people in charge no longer have an account', async () => {
      vi.mocked(emailsOfHolders).mockResolvedValue(['owner@x.fr']);
      const orphan = event({ assignees: [{ login: 'gone', user: null }] });
      vi.mocked(prisma.event.findMany).mockResolvedValue([orphan] as never);

      await runReminderTick(now);

      expect(deliver).toHaveBeenCalledWith('eventReminder', expect.anything(), ['owner@x.fr']);
    });

    it('is not used when someone in charge can be written to', async () => {
      vi.mocked(prisma.event.findMany).mockResolvedValue([event()] as never);

      await runReminderTick(now);

      expect(emailsOfHolders).not.toHaveBeenCalled();
      expect(deliver).toHaveBeenCalledWith('eventReminder', expect.anything(), ['alice@x.fr']);
    });

    it('is not even looked up on a chat channel, which needs no recipient', async () => {
      setConfig({ channel: 'discord' });
      vi.mocked(prisma.event.findMany).mockResolvedValue([event({ assignees: [] })] as never);

      await runReminderTick(now);

      expect(emailsOfHolders).not.toHaveBeenCalled();
      expect(deliver).toHaveBeenCalledWith('eventReminder', expect.anything(), []);
    });
  });
});

describe('runReminderTick — a series with dates of their own', () => {
  const OCT10 = new Date('2026-10-10T18:00:00Z');
  const OCT17 = new Date('2026-10-17T18:00:00Z');

  const own = (
    occurrenceStart: Date,
    values: Partial<StoredOccurrence> = {},
  ): StoredOccurrence => ({
    occurrenceStart,
    title: null,
    description: null,
    location: null,
    categoryKey: null,
    status: null,
    startsAt: null,
    endsAt: null,
    assigneesOverridden: false,
    confirmationNotifiedAt: null,
    updatedAt: new Date('2026-09-02T10:00:00Z'),
    assignees: [],
    ...values,
  });
  const series = (overrides: Partial<StoredEvent> = {}) =>
    event({
      repeat: { freq: 'WEEKLY', interval: 1 },
      recurrenceUntil: new Date('2026-10-31T00:00:00Z'),
      ...overrides,
    });

  it('does not remind a date that went back to draft, and still reminds the others', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([
      series({ occurrences: [own(OCT10, { status: 'DRAFT' })] }),
    ] as never);

    await runReminderTick(new Date('2026-10-09T17:00:00Z'));
    expect(deliver).not.toHaveBeenCalled();

    await runReminderTick(new Date('2026-10-16T17:00:00Z'));
    expect(deliver).toHaveBeenCalledTimes(1);
  });

  it('reminds only the dates confirmed on their own when the rest of the series is a draft', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([
      series({
        status: 'DRAFT',
        occurrences: [
          own(OCT17, {
            status: 'CONFIRMED',
            confirmationNotifiedAt: new Date('2026-09-02T10:00:00Z'),
          }),
        ],
      }),
    ] as never);

    await runReminderTick(new Date('2026-10-09T17:00:00Z'));
    expect(deliver).not.toHaveBeenCalled();

    await runReminderTick(new Date('2026-10-16T17:00:00Z'));
    expect(deliver).toHaveBeenCalledTimes(1);
    expect(prisma.eventReminder.create).toHaveBeenCalledWith({
      data: { eventId: 'evt1', occurrenceStart: OCT17 },
    });
  });

  it('reminds a moved date the evening before its new day, once, under the date the series gave it', async () => {
    // The 17th moved to the 20th, same hour.
    const moved = own(OCT17, {
      startsAt: new Date('2026-10-20T18:00:00Z'),
      endsAt: new Date('2026-10-20T21:00:00Z'),
    });
    vi.mocked(prisma.event.findMany).mockResolvedValue([series({ occurrences: [moved] })] as never);

    // The evening before the 17th: nothing, the date is no longer there.
    await runReminderTick(new Date('2026-10-16T17:00:00Z'));
    expect(prisma.eventReminder.create).not.toHaveBeenCalledWith({
      data: { eventId: 'evt1', occurrenceStart: OCT17 },
    });

    // The evening before the 20th: the reminder, claimed under the original start, and never a second time.
    await runReminderTick(new Date('2026-10-19T17:00:00Z'));
    await runReminderTick(new Date('2026-10-19T17:05:00Z'));
    expect(prisma.eventReminder.create).toHaveBeenCalledWith({
      data: { eventId: 'evt1', occurrenceStart: OCT17 },
    });
    expect(deliver).toHaveBeenCalledTimes(1);
    expect(vi.mocked(toNotificationData).mock.calls.at(-1)?.[1]).toMatchObject({
      start: new Date('2026-10-20T18:00:00Z'),
    });
  });

  it('writes to the members in charge of that date when it has its own', async () => {
    const bob = { login: 'bob', user: { fullName: 'Bob', email: 'bob@x.fr' } };
    vi.mocked(prisma.event.findMany).mockResolvedValue([
      series({ occurrences: [own(OCT10, { assigneesOverridden: true, assignees: [bob] })] }),
    ] as never);

    await runReminderTick(new Date('2026-10-09T17:00:00Z'));
    expect(deliver).toHaveBeenCalledWith('eventReminder', expect.anything(), ['bob@x.fr']);

    await runReminderTick(new Date('2026-10-16T17:00:00Z'));
    expect(deliver).toHaveBeenLastCalledWith('eventReminder', expect.anything(), ['alice@x.fr']);
  });

  it('does not remind a date confirmed on its own after its reminder was due: members were just told', async () => {
    vi.mocked(prisma.event.findMany).mockResolvedValue([
      series({
        status: 'DRAFT',
        occurrences: [
          own(OCT10, {
            status: 'CONFIRMED',
            confirmationNotifiedAt: new Date('2026-10-09T17:30:00Z'),
          }),
        ],
      }),
    ] as never);

    await runReminderTick(new Date('2026-10-09T17:45:00Z'));
    expect(deliver).not.toHaveBeenCalled();
  });
});

