const mocks = vi.hoisted(() => ({ manager: vi.fn(), status: vi.fn() }));

vi.mock('@/lib/settings/access', () => ({ getSettingsManager: mocks.manager }));
vi.mock('@/lib/updates/status', () => ({ updateStatus: mocks.status }));

